"""TC-04: geometric closes give constant log returns ln(1.01) and ln(0.98) (RISK-01)."""

from __future__ import annotations

import math

import pytest

from mdata.types import Prices
from risk.returns import log_returns


def _tc04(golden):
    raw, expected = golden("risk", "TC-04")
    prices = raw["prices"]
    return (
        Prices(
            dates=tuple(prices["dates"]),
            tickers=tuple(prices["tickers"]),
            closes={ticker: tuple(closes) for ticker, closes in prices["closes"].items()},
        ),
        expected,
    )


def test_tc04_dates_and_tickers(golden):
    prices, expected = _tc04(golden)
    returns = log_returns(prices)
    assert returns.base_date == expected["base_date"]
    assert returns.dates == tuple(expected["dates"])
    assert returns.tickers == tuple(expected["tickers"])


def test_tc04_every_return_matches_expected(golden):
    prices, expected = _tc04(golden)
    returns = log_returns(prices)
    for ticker in expected["tickers"]:
        assert returns.values[ticker] == pytest.approx(
            tuple(expected["values"][ticker]), rel=0, abs=expected["tol"]
        )


def test_tc04_every_return_equals_closed_form(golden):
    prices, expected = _tc04(golden)
    returns = log_returns(prices)
    closed_form = {"X": math.log(1.01), "Y": math.log(0.98)}
    for ticker, rate in closed_form.items():
        assert all(abs(r - rate) <= expected["tol"] for r in returns.values[ticker])

